mapper.select:
select to2.*,COALESCE(t_unread.unread_num, 0) AS unread_num, tc.id as comment_id from t_order to2
    left join t_comment tc on tc.order_id = to2.id
     left join
         (
            select order_no,count(*) as unread_num
            from t_message tm

                tm.status = 0

                    and tm.receive_user_id = #{param2.lawyerUserId}


                    and tm.receive_user_id = #{param2.userId}


            group by order_no
         ) as t_unread
     on to2.order_no = t_unread.order_no


        and to2.status = #{param2.status}


        and to2.lawyer_user_id = #{param2.lawyerUserId}


        and to2.user_id = #{param2.userId}
